  'help.ticketSent': 'Ticket Naipadala!',
  'help.ticketSentDesc': 'Natanggap namin ang iyong kahilingan. Sasagutin ng aming koponan sa pamamagitan ng email sa loob ng 24 na oras.',
  'help.close': 'Isara',
  'help.ticketError': 'Nabigong magpadala ng ticket. Subukan muli.',
  'help.type.cant_login': 'Hindi ako makapasok',
  'help.type.email_issue': 'Problema sa email',
  'help.type.security': 'Seguridad',
  'help.type.other': 'Iba pa',
  'help.faq.cantLogin.q': 'Hindi ko ma-access ang aking account',
  'help.faq.cantLogin.a': 'Suriin kung ginagamit mo ang tamang email at password. Kung nakalimutan mo ang password, i-click ang "Nakalimutan ang password?" sa login screen. Kung patuloy ang problema, lumikha ng support ticket.',
  'help.faq.notReceiving.q': 'Hindi ako tumatanggap ng mga email',
  'help.faq.notReceiving.a': 'Suriin ang Spam folder muna. Tiyaking hindi puno ang iyong storage. Kung patuloy ang problema, tiyaking tama ang address ng nagpadala at lumikha ng ticket.',
  'help.faq.cantSend.q': 'Hindi ako makapagpadala ng mga email',
  'help.faq.cantSend.a': 'Suriin ang iyong koneksyon sa internet at kung tama ang address ng tatanggap. Tiyaking hindi lalampas sa 25MB ang mga attachment. Subukan muli sa ilang minuto.',
  'help.faq.forgotPassword.q': 'Nakalimutan ko ang aking password',
  'help.faq.forgotPassword.a': 'Sa login screen, i-click ang "Nakalimutan ang password?" at sundin ang mga tagubilin para i-reset ang iyong password sa pamamagitan ng recovery email.',
  'help.faq.accountSecurity.q': 'Sa tingin ko ay na-compromise ang aking account',
  'help.faq.accountSecurity.a': 'Agad na palitan ang iyong password. Suriin ang Sent folder para sa mga mensaheng hindi mo ipinadala. I-enable ang two-step authentication sa Settings > Security. Kung kinakailangan, lumikha ng urgent ticket.',
  'help.faq.appAccess.q': 'Paano ko ma-access ang app sa cellphone?',
  'help.faq.appAccess.a': 'Maaari mong ma-access ang Chatyy sa browser sa chatyy.com.br, o i-download ang aming app sa app store ng iyong device.',
  'privacy.title': 'Patakaran sa Privacy',
  'privacy.subtitle': 'Paano namin pinoprotektahan at pinangangasiwaan ang iyong data',
  'privacy.lastUpdated': 'Huling na-update: Marso 2026',
  'privacy.dataCollection.title': 'Pagkolekta ng Data',
  'privacy.dataCollection.body': 'Kumokolekta kami ng mga impormasyong kinakailangan lamang para sa serbisyo ng email: ang iyong pangalan, email address, at nilalaman ng mga mensaheng ipinadala at natanggap. Hindi namin ibinebenta o ibinabahagi ang iyong personal na data sa mga third party para sa mga layuning pang-marketing.',
  'privacy.dataUsage.title': 'Paano Namin Ginagamit ang Iyong Data',
  'privacy.dataUsage.body': 'Ang iyong data ay ginagamit lamang para patakbuhin at pagbutihin ang serbisyo ng email, kabilang ang paghahatid ng mga mensahe, spam filtering, mga tampok ng AI (na may iyong pahintulot) at seguridad ng account.',
  'privacy.dataSecurity.title': 'Seguridad ng Data',
  'privacy.dataSecurity.body': 'Gumagamit kami ng industry-standard encryption (TLS/SSL) para sa lahat ng data in transit at at rest. Ang mga session ay protektado ng encrypted tokens at CSRF protection. Regular naming sinusuri ang aming mga gawi sa seguridad.',
  'privacy.cookies.title': 'Cookies at Local Storage',
  'privacy.cookies.body': 'Gumagamit kami ng mga essential cookies at local storage para mapanatili ang iyong session, alalahanin ang iyong mga preference (tema, wika) at magbigay ng maayos na karanasan. Hindi kami gumagamit ng third-party tracking cookies.',
  'privacy.thirdParties.title': 'Mga Serbisyo ng Third Party',
  'privacy.thirdParties.body': 'Maaari kaming gumamit ng mga third-party services para sa mga tiyak na functionality tulad ng AI (Anthropic Claude) at push notifications. Ang mga serbisyong ito ay sumusunod sa kanilang sariling mga patakaran sa privacy at nagpoproseso lamang ng minimum na kinakailangang data.',
  'privacy.rights.title': 'Iyong Mga Karapatan',
  'privacy.rights.body': 'May karapatan kang ma-access, ituwid, i-export o i-delete ang iyong personal na data anumang oras. Maaari mong pamahalaan ang iyong data sa Settings o makipag-ugnayan sa aming support.',
  'privacy.contact.title': 'Makipag-ugnayan sa Amin',
  'privacy.contact.body': 'Para sa mga katanungan tungkol sa privacy o mga kahilingan sa data, makipag-ugnayan sa privacy@chatyy.com.br. Sasagutin namin ito sa loob ng 30 araw.',
  'terms.title': 'Mga Tuntunin ng Serbisyo',
  'terms.subtitle': 'Mga patnubay sa paggamit ng Chatyy',
  'terms.lastUpdated': 'Huling na-update: Marso 2026',
  'terms.acceptance.title': 'Pagtanggap sa Mga Tuntunin',
  'terms.acceptance.body': 'Sa pag-access o paggamit ng Chatyy, sumasang-ayon ka sa mga Tuntunin ng Serbisyo na ito. Kung hindi ka sumasang-ayon sa anumang bahagi ng mga tuntuning ito, huwag gamitin ang serbisyo.',
  'terms.services.title': 'Paglalarawan ng Mga Serbisyo',
  'terms.services.body': 'Nagbibigay ang Chatyy ng mga serbisyo ng komunikasyon sa email kabilang ang pagpapadala, pagtanggap at pamamahala ng mga email, pati na rin ang mga tampok ng AI, integration sa calendar at videoconferencing.',
  'terms.accounts.title': 'Mga Account ng User',
  'terms.accounts.body': 'Ikaw ang responsable sa pagpapanatili ng seguridad ng iyong mga kredensyal. Huwag ibahagi ang iyong password o payagan ang hindi awtorisadong pag-access sa iyong account. Dapat ay hindi bababa sa 13 taong gulang ka upang gumamit ng serbisyong ito.',
  'terms.conduct.title': 'Tamang Paggamit',
  'terms.conduct.body': 'Sumasang-ayon kang hindi gamitin ang serbisyo para magpadala ng spam, malware, phishing o anumang ilegal na nilalaman. Huwag subukang i-access ang mga account ng ibang user o hadlangan ang imprastruktura ng serbisyo.',
  'terms.content.title': 'Pagmamay-ari ng Nilalaman',
  'terms.content.body': 'Nananatili ang iyong pagmamay-ari sa lahat ng nilalaman na iyong nilikha at ipinadala sa pamamagitan ng serbisyo. Wala kaming pag-aangkin sa iyong mga email o attachment. Maaari naming iproseso ang nilalaman kung kinakailangan upang maibigay ang serbisyo.',
  'terms.limitation.title': 'Limitasyon ng Pananagutan',
  'terms.limitation.body': 'Ang Chatyy ay ibinibigay "as is". Nagsusumikap kaming magkaroon ng 99.9% availability ngunit hindi namin ginagarantiyahan ang tuloy-tuloy na serbisyo. Hindi kami mananagot para sa mga hindi tuwirang, incidental o consequential na pinsala na dulot ng paggamit ng serbisyo.',
  'terms.termination.title': 'Pagsasara ng Account',
  'terms.termination.body': 'Maaari naming suspindihin o isara ang mga account na lumalabag sa mga tuntuning ito. Maaari mong tanggalin ang iyong account anumang oras sa Settings. Pagkatapos ng pagsasara, ang iyong data ay tatanggalin sa loob ng 30 araw.',
  'terms.changes.title': 'Mga Pagbabago sa Mga Tuntunin',
  'terms.changes.body': 'Maaari naming i-update ang mga tuntuning ito paminsan-minsan. Ipapaalam namin ang tungkol sa mga makabuluhang pagbabago sa pamamagitan ng email o notification sa app. Ang patuloy na paggamit pagkatapos ng mga pagbabago ay itinuturing na pagtanggap sa mga na-update na tuntunin.',
