  'plans.familyIncludesPlus': 'Kasama sa iyong Pro plan ang lahat mula sa Chatyy Plus',
  'plans.storageWarning': 'Gumagamit ka ng {used} mula sa {total}',
  'plans.storageWarningUpgrade': 'Mag-upgrade sa Chatyy One at makakuha ng 200 GB!',
  'plans.faqWhatIsPlus': 'Ano ang Chatyy One?',
  'plans.faqWhatIsPlusAnswer': 'Ito ang premium na plano ng Chatyy na nagpoprotekta sa lahat ng iyong pag-uusap, mga larawan, at mga video. Sa Chatyy One, kahit na mag-delete ka ng isang bagay nang hindi sinasadya, maaari mo itong ma-recover sa loob ng 30 araw. Bukod dito, makakakuha ka ng 200GB na imbakan, One AI bilang personal na katulong, at maaari kang magpadala ng mga file na hanggang 100MB.',
  'plans.faqCancelAnswer': 'Mananatiling aktibo ang iyong plano hanggang sa katapusan ng bayad na panahon. Pagkatapos nito, babalik ka sa libreng plano. Ang iyong mga larawan at video na lalampas sa 15GB ay mananatili ng 30 araw para ma-download mo.',
  'plans.faqHowFamily': 'Paano gumagana ang Pro plan?',
  'plans.faqHowFamilyAnswer': 'Maaari kang magdagdag ng hanggang 4 na tao mula sa iyong pamilya. Lahat ay nagbabahagi ng 500GB na imbakan at tumatanggap ng lahat ng benepisyo ng Chatyy One. Bawat tao ay may sariling pribadong espasyo — walang makakakita sa mga file ng iba.',
  'plans.faqChangePlanAnswer': 'Oo! Kung mag-upgrade ka mula sa Plus patungong Pro, ang tanging sisingilin ay ang proporsyonal na pagkakaiba. Kung magda-downgrade ka, ang kasalukuyang plano ay mananatili hanggang sa katapusan ng panahon.',
  'plans.faqCardDeclined': 'Tinanggihan ang aking card, ano ang gagawin ko?',
  'plans.faqCardDeclinedAnswer': 'Mayroon kang 7 araw upang i-update ang iyong card. Sa panahong ito, lahat ng iyong benepisyo ay patuloy na gagana. Pagkatapos ng 7 araw, ang plano ay babalik sa libre.',
  'plans.faqDataSafe': 'Ligtas ba ang aking data?',
  'plans.faqDataSafeAnswer': 'Oo! Ang iyong mga detalye sa pagbabayad ay pinoproseso gamit ang end-to-end encryption. Hindi namin iniimbak ang numero ng iyong card — tanging ang huling 4 na digit para sa iyong sanggunian.',
